  "m3.qa.brief_description": "Description is very concise. Additional technical context helps investigators.",
  "m3.qa.disclaimer_unofficial": "AI Review Notice: This automated audit checks structure, completeness, and privacy. It does not constitute official governmental verification.",
  "m3.qa.exposed_card": "Valid 16-digit payment card number detected. Redact card numbers to preserve privacy.",
  "m3.qa.exposed_otp": "Potential secret authentication credential or OTP detected in text. Redact before submission.",
  "m3.qa.invalid_loss_format": "Financial loss must be recorded as a valid numeric amount in Ethiopian Birr (ETB).",
  "m3.qa.missing_date": "Incident date is not specified. An approximate date is required for institutional logging.",
