  "m3.routing.why.cbe_fraud": "Commercial Bank of Ethiopia administers your account ledger. An immediate electronic debit block must be enacted by bank fraud operations before stolen funds clear interbank transfer settlement.",
  "m3.routing.why.police_prosecution": "Formal criminal prosecution, court subpoenas, and asset tracing against perpetrators require filing an official signed statement at the Federal Police CID.",
  "m3.routing.why.telebirr": "Only Ethio Telecom maintains the Telebirr payment network ledger. They have the administrative power to freeze compromised wallets, flag recipient phone numbers, and investigate unauthorized merchant debits.",
  "m3.routing.why.police_fraud": "If financial loss occurred and you intend to pursue criminal restitution, filing a police case report creates the evidentiary basis for court action.",
  "m3.routing.why.cbe_birr": "CBE administers the CBE Birr wallet and holds jurisdiction over affiliated agent transactions and branch dispute procedures.",
  "m3.routing.why.insa_banking_threat": "If the banking fraud originated from a systemic SMS phishing campaign or rogue banking application, Ethio-CERT coordinates national threat neutralization.",
  "m3.routing.why.meta_facebook": "Meta operates dedicated automated cryptographic identity verification workflows (including video selfies and email change rollback) to restore hijacked accounts.",
  "m3.routing.why.meta_instagram": "Instagram provides in-app biometric video selfie verification and secure backup email challenges to recover compromised profiles.",
  "m3.routing.why.microsoft": "Microsoft automated security validates ownership using historical passwords, familiar devices, and registered security questions.",
  "m3.routing.why.ethio_cert_national": "Ethio-CERT is Ethiopia's national CSIRT mandated to analyze malware samples, take down fraudulent domains, and coordinate emergency cyber defense across critical infrastructure.",
  "m3.routing.why.police_extortion": "Ransomware extortion demands constitute criminal blackmail under Ethiopian computer crime laws and should be formally logged with law enforcement.",
  "m3.routing.why.telecom_sim": "Ethio Telecom is the sole provider able to verify SIM status, reissue physical SIM cards, and conduct mandatory in-person identity verification.",
  "m3.routing.why.platform_abuse": "Platform trust & safety teams possess the technical capability to ban abusive profiles, remove non-consensual content, and terminate violator sessions.",
  "m3.routing.why.police_threats": "Direct threats to life, physical extortion, or criminal coercion must be reported to the Federal Police Crime Investigation Bureau.",
  "m3.routing.why.custodian_org": "The organization storing the exposed database has the direct technical responsibility to patch the breach, assess exposure, and notify affected citizens.",
  "m3.routing.why.insa_national_breach": "INSA monitors national data privacy disclosures and coordinates remediation for public and corporate leaks.",
  "m3.routing.why.general_guidance": "Ethio-CERT can assess complex or uncategorized cyber threats and direct you to the appropriate specialized authority.",
  "m3.routing.prepare.bank_statement": "Certified bank statement showing the unauthorized debit transaction, transaction reference number, and recipient account.",
  "m3.routing.prepare.police_file": "Original National ID, printout of bank statements, SMS notifications, and chronologically recorded suspect communications.",
  "m3.routing.prepare.telebirr_trans": "Transaction reference SMS from 127, sender phone number, date/time, and original National ID.",
  "m3.routing.prepare.telecom_statement": "Telecom dispute receipt number, registered SIM phone number, and evidence of financial loss.",
  "m3.routing.prepare.cbe_birr_trans": "Transaction confirmation code, transaction timestamp, debited amount, and registered phone number.",
  "m3.routing.prepare.sms_phishing": "Uncropped screenshot of the deceptive SMS, sender phone number, and phishing website URL.",
  "m3.routing.prepare.fb_account": "Original email address or phone number used to register the account, past passwords, and familiar hardware device.",
  "m3.routing.prepare.ig_selfie": "Smartphone with front camera for video selfie verification, and registered account username.",
  "m3.routing.prepare.microsoft_info": "Alternate working email address, past passwords, and recent Outlook email subject lines or contacts.",
  "m3.routing.prepare.phishing_artifacts": "Deceptive website URL, full email headers, rogue APK file name, or screenshot of extortion screen.",
  "m3.routing.prepare.ransom_notes": "Photographs of the ransom demand note, encrypted file extensions, and attacker payment address. Do NOT alter encrypted files.",
  "m3.routing.prepare.fayda_id": "Physical Ethiopian National ID (Fayda / Kebele / Passport), and original SIM card packaging if available.",
