  "m4.quiz.title": "Website Security Knowledge Quiz",
  "m4.quiz.desc": "Test your understanding of transport security, defensive HTTP headers, and cookie protection.",
  "m4.quiz.score": "Your Score",
  "m4.quiz.q1": "Why is HSTS critical even if you already redirect HTTP to HTTPS with HTTP 301?",
  "m4.quiz.q1_o1": "An attacker on an open network can intercept the very first HTTP request before the redirect happens (SSL stripping).",
  "m4.quiz.q1_o2": "HSTS makes website images and CSS stylesheets load twice as fast.",
  "m4.quiz.q1_o3": "HSTS automatically purchases and renews expired TLS certificates.",
  "m4.quiz.q2": "Which cookie attribute directly prevents stolen session tokens via Cross-Site Scripting (XSS)?",
  "m4.quiz.q2_o1": "HttpOnly (blocks JavaScript access to session tokens).",
  "m4.quiz.q2_o2": "Domain (limits cookie to subdomains).",
  "m4.quiz.q2_o3": "Max-Age=3600 (expires cookie after one hour).",
  "m4.quiz.q3": "Why should production servers suppress 'Server' and 'X-Powered-By' headers?",
  "m4.quiz.q3_o1": "To prevent automated scanners and attackers from easily identifying exact versions for known CVE exploits.",
  "m4.quiz.q3_o2": "Because modern browsers crash if more than 3 response headers are sent.",
  "m4.quiz.q3_o3": "To prevent internet search engines from indexing the domain.",
  "m4.quiz.q4": "In scenario DS-C, why are checks CHK-02 through CHK-07 marked as 'Unknown'?",
  "m4.quiz.q4_o1": "The browser aborted the connection during TLS handshake due to expired certificate, so no HTTP headers were received.",
  "m4.quiz.q4_o2": "The website owner disabled HTTP headers on weekends.",
  "m4.quiz.q4_o3": "HTTP headers are only supported on unencrypted HTTP connections.",
