  "academy.stage1.title": "Stage 1: Essential Awareness to Strategic Defense (Levels 1–6)",
  "academy.stage1.desc": "Master foundational cybersecurity, threat recognition, privacy, incident response, and defensive website architecture.",
  "academy.stage2.title": "Stage 2: Professional Cyber Defense (Levels 7–10)",
  "academy.stage2.desc": "Applied defensive operations, telemetry monitoring, incident triage, and bastion administration.",
  "academy.stage3.title": "Stage 3: Advanced Security Engineering (Levels 11–15)",
  "academy.stage3.desc": "Deep technical software security, API defense, identity architecture (Zero Trust), and cryptographic engineering.",
  "academy.stage4.title": "Stage 4: Continuing Mastery & Specialization (Level 16+)",
  "academy.stage4.desc": "Specialized tracks (Incident Commander, Cloud Architect, Threat Intel), case studies, and capstone projects.",
  "academy.lvl7.title": "Level 7: Defensive Telemetry & Log Monitoring",
  "academy.lvl7.desc": "Security log ingestion, auth anomaly detection, event correlation, and defensive telemetry.",
  "academy.lvl8.title": "Level 8: Security Incident Analysis & Triage",
  "academy.lvl8.desc": "Triage methodology, memory/disk containment, chain of custody, and forensic evidence collection.",
  "academy.lvl9.title": "Level 9: Hardened System & Bastion Administration",
  "academy.lvl9.desc": "OS hardening (Linux CIS benchmarks, Windows GPO), SSH bastions, and least-privilege RBAC.",
  "academy.lvl10.title": "Level 10: Network Edge Defense & Perimeter Firewalls",
  "academy.lvl10.desc": "Stateful packet inspection, ingress/egress filtering, DMZ segmentation, and IDS/IPS.",
  "academy.lvl11.title": "Level 11: Secure Software Engineering & Threat Modeling",
  "academy.lvl11.desc": "STRIDE threat modeling, secure SDLC, safe parameterization, and input sanitization.",
  "academy.lvl12.title": "Level 12: Web Application Security & API Defense",
  "academy.lvl12.desc": "OWASP Top 10, CSRF defense, CORS misconfigurations, and REST API rate limiting.",
  "academy.lvl13.title": "Level 13: Identity Architecture & Zero Trust",
  "academy.lvl13.desc": "Zero Trust architecture, OAuth 2.0 PKCE, OpenID Connect, and continuous verification.",
  "academy.lvl14.title": "Level 14: Cryptographic Engineering & Key Management",
  "academy.lvl14.desc": "Symmetric/asymmetric algorithms, forward secrecy, KMS key rotation, and hash algorithms.",
  "academy.lvl15.title": "Level 15: Enterprise Security Architecture & Risk Analysis",
  "academy.lvl15.desc": "Risk assessment frameworks (NIST CSF, ISO 27001), threat modeling, and resilience planning.",
  "academy.lvl16.title": "Level 16+: Continuing Mastery & Defensive Specialization Tracks",
  "academy.lvl16.desc": "Specialized defensive tracks, live case studies, threat intelligence, and capstone evaluation.",
  "academy.sim.title": "Cybersecurity Simulation Lab",
  "academy.sim.desc": "Hands-on defensive scenario challenges based on realistic Ethiopian threat vectors. Test your response skills safely.",
